16	package org.springframework.samples.petclinic.util;
17	
18	import java.util.Locale;
19	import java.util.regex.Pattern;
20	
21	/**
22	 * Normalizes free-text values so they can be compared for equality regardless of surrounding or
23	 * repeated whitespace and letter case. Leading and trailing whitespace is trimmed, every internal
24	 * run of whitespace is collapsed to a single space, and the result is lower-cased.
25	 */
26	public final class TextNormalizer {
27	
28	    private static final Pattern WHITESPACE = Pattern.compile("\\s+");
29	
30	    private TextNormalizer() {
31	    }
32	
33	    /**
34	     * Produces a canonical form of the supplied value for case-insensitive, whitespace-insensitive
35	     * comparison.
36	     *
37	     * @param value the raw value, may be {@code null}
38	     * @return the normalized value, or an empty string when {@code value} is {@code null}
39	     */
40	    public static String normalizeForComparison(String value) {
41	        if (value == null) {
42	            return "";
43	        }
44	        return WHITESPACE.matcher(value.trim()).replaceAll(" ").toLowerCase(Locale.ROOT);
45	    }
46	}
