16	package org.springframework.samples.petclinic.util;
17	
18	import java.nio.charset.StandardCharsets;
19	import java.security.MessageDigest;
20	import java.security.NoSuchAlgorithmException;
21	
22	/**
23	 * Renders SHA-256 digests as upper-case hexadecimal. Shared by the stable identifiers the
24	 * application derives from owner fields — the household id and the customer code — so the digest
25	 * and hex-encoding logic lives in one place.
26	 */
27	public final class Sha256 {
28	
29	    private Sha256() {
30	    }
31	
32	    /**
33	     * Produce the first {@code length} upper-case hex characters of the SHA-256 digest of the UTF-8
34	     * bytes of {@code input}.
35	     *
36	     * @param input the value to hash
37	     * @param length the number of leading hex characters to keep
38	     * @return the upper-case hex prefix of the digest
39	     */
40	    public static String hexPrefix(String input, int length) {
41	        try {
42	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(input.getBytes(StandardCharsets.UTF_8));
43	            StringBuilder hex = new StringBuilder(length);
44	            for (int i = 0; hex.length() < length; i++) {
45	                hex.append(String.format("%02X", digest[i]));
46	            }
47	            return hex.substring(0, length);
48	        } catch (NoSuchAlgorithmException ex) {
49	            // SHA-256 is required to be available on every JVM, so this cannot happen.
50	            throw new IllegalStateException("SHA-256 algorithm not available", ex);
51	        }
52	    }
53	}
