16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	import org.springframework.samples.petclinic.util.Luhn;
20	import org.springframework.samples.petclinic.util.RegistrationDatePolicy;
21	
22	import jakarta.persistence.*;
23	import jakarta.validation.constraints.NotEmpty;
24	import jakarta.validation.constraints.Pattern;
25	
26	import java.time.LocalDate;
27	import java.util.*;
28	
29	/**
30	 * Simple JavaBean domain object representing an owner.
31	 *
32	 * @author Ken Krebs
33	 * @author Juergen Hoeller
34	 * @author Sam Brannen
35	 * @author Michael Isvy
36	 */
37	@Entity
38	@Table(name = "owners")
39	public class Owner extends Person {
40	    @Column(name = "address")
41	    @NotEmpty
42	    private String address;
43	
44	    @Column(name = "city")
45	    @NotEmpty
46	    private String city;
47	
48	    @Column(name = "postcode")
49	    private String postcode;
50	
51	    @Column(name = "telephone")
52	    @NotEmpty
53	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form")
54	    private String telephone;
55	
56	    @Column(name = "email")
57	    private String email;
58	
59	    @Column(name = "birth_date")
60	    private LocalDate birthDate;
61	
62	    @Column(name = "registration_date")
63	    private LocalDate registrationDate;
64	
65	    @Column(name = "customer_code")
66	    private String customerCode;
67	
68	    @Column(name = "household_id")
69	    private String householdId;
70	
71	    @Column(name = "namesake_count")
72	    private Integer namesakeCount;
73	
74	    @Column(name = "household_size")
75	    private Integer householdSize;
76	
77	    @Column(name = "possible_duplicate")
78	    private Boolean possibleDuplicate;
79	
80	    @Column(name = "possible_duplicate_of")
81	    private Integer possibleDuplicateOf;
82	
83	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
84	    private Set<Pet> pets;
85	
86	    /**
87	     * Resolve the registration date at creation time: default it to the server's
88	     * current date when none was supplied, and roll a weekend date forward to the
89	     * next business day so every value derived from it (such as the membership
90	     * number's year segment) uses the adjusted date.
91	     */
92	    @PrePersist
93	    private void resolveRegistrationDate() {
94	        this.registrationDate = RegistrationDatePolicy.effectiveDate(this.registrationDate);
95	    }
96	
97	    public String getAddress() {
98	        return this.address;
99	    }
100	
101	    public void setAddress(String address) {
102	        this.address = address;
103	    }
104	
105	    public String getCity() {
106	        return this.city;
107	    }
108	
109	    public void setCity(String city) {
110	        this.city = city;
111	    }
112	
113	    public String getPostcode() {
114	        return this.postcode;
115	    }
116	
117	    public void setPostcode(String postcode) {
118	        this.postcode = postcode;
119	    }
120	
121	    /**
122	     * The owner's locality: the region component of its {@link #customerCode}
123	     * identity (see {@link CustomerCode}), or {@code null} when no customer code
124	     * is assigned. The region was derived from the owner's postcode and city when
125	     * the identity was minted, so the locality now follows the identity rather than
126	     * being recomputed from the current city and postcode.
127	     */
128	    public String getLocality() {
129	        return CustomerCode.regionOf(this.customerCode);
130	    }
131	
132	    public String getTelephone() {
133	        return this.telephone;
134	    }
135	
136	    public void setTelephone(String telephone) {
137	        this.telephone = telephone;
138	    }
139	
140	    public String getEmail() {
141	        return this.email;
142	    }
143	
144	    public void setEmail(String email) {
145	        this.email = email;
146	    }
147	
148	    public LocalDate getBirthDate() {
149	        return this.birthDate;
150	    }
151	
152	    public void setBirthDate(LocalDate birthDate) {
153	        this.birthDate = birthDate;
154	    }
155	
156	    /**
157	     * The owner's {@link AgeBand age band} on the {@link #registrationDate}, derived
158	     * from the {@link #birthDate}, or {@code null} when no birth date is on file.
159	     */
160	    public AgeBand getAgeBand() {
161	        return AgeBand.on(this.birthDate, this.registrationDate);
162	    }
163	
164	    public LocalDate getRegistrationDate() {
165	        return this.registrationDate;
166	    }
167	
168	    public void setRegistrationDate(LocalDate registrationDate) {
169	        this.registrationDate = registrationDate;
170	    }
171	
172	    public String getCustomerCode() {
173	        return this.customerCode;
174	    }
175	
176	    public void setCustomerCode(String customerCode) {
177	        this.customerCode = customerCode;
178	    }
179	
180	    /**
181	     * The owner's membership number, formatted {@code '<customerCode>-M<YY>'}
182	     * where {@code YY} is the last two digits of the {@link #registrationDate}
183	     * year (e.g. {@code "NSW-3F2A9C1D-M26"}). Derived from the owner's own fields.
184	     */
185	    public String getMembershipNumber() {
186	        if (this.customerCode == null || this.registrationDate == null) {
187	            return null;
188	        }
189	        return String.format("%s-M%02d", this.customerCode, this.registrationDate.getYear() % 100);
190	    }
191	
192	    /**
193	     * The Luhn check digit (0-9) computed over the digits of the
194	     * {@link #customerCode}, or {@code null} when no customer code is assigned.
195	     */
196	    public Integer getCheckDigit() {
197	        if (this.customerCode == null) {
198	            return null;
199	        }
200	        return Luhn.checkDigit(this.customerCode);
201	    }
202	
203	    public String getHouseholdId() {
204	        return this.householdId;
205	    }
206	
207	    public void setHouseholdId(String householdId) {
208	        this.householdId = householdId;
209	    }
210	
211	    /**
212	     * The owner's identity key: the single derived value used to detect duplicate owners. It is the
213	     * normalized telephone, the (lower-cased) email or an empty string when absent, and the
214	     * household id or an empty string when absent, joined with {@code '|'} (e.g.
215	     * {@code "+61412345678|jo@example.com|3F2A9C1D4B6E8071"}). Two owners are the same person only
216	     * when their whole identity keys are equal; because the telephone is part of the key, household
217	     * members with different telephones have different keys.
218	     */
219	    public String getIdentityKey() {
220	        return String.join("|",
221	            this.telephone == null ? "" : this.telephone,
222	            this.email == null ? "" : this.email,
223	            this.householdId == null ? "" : this.householdId);
224	    }
225	
226	    /**
227	     * The owner's membership level, a number from 1 to 3 derived from the
228	     * owner's own fields. Starts at {@code 1}, gains {@code 1} when a contact
229	     * email is on file, gains {@code 1} when the owner has no namesakes, and is
230	     * capped at {@code 3}. (Level {@code 4} is reserved for tenure.)
231	     */
232	    public Integer getMembershipLevel() {
233	        int level = 1;
234	        boolean hasEmail = this.email != null && !this.email.isEmpty();
235	        if (hasEmail) {
236	            level += 1;
237	        }
238	        boolean noNamesakes = this.namesakeCount != null && this.namesakeCount == 0;
239	        if (noNamesakes) {
240	            level += 1;
241	        }
242	        return Math.min(level, 3);
243	    }
244	
245	    /**
246	     * The owner's preferred contact channel, derived from the fields on file:
247	     * {@code "EMAIL"} when a contact email is present, otherwise {@code "PHONE"}.
248	     */
249	    public String getContactPreference() {
250	        boolean hasEmail = this.email != null && !this.email.isEmpty();
251	        return hasEmail ? "EMAIL" : "PHONE";
252	    }
253	
254	    public Integer getNamesakeCount() {
255	        return this.namesakeCount;
256	    }
257	
258	    public void setNamesakeCount(Integer namesakeCount) {
259	        this.namesakeCount = namesakeCount;
260	    }
261	
262	    public Integer getHouseholdSize() {
263	        return this.householdSize;
264	    }
265	
266	    public void setHouseholdSize(Integer householdSize) {
267	        this.householdSize = householdSize;
268	    }
269	
270	    /**
271	     * Whether this owner, while not a hard duplicate, shares an existing owner's
272	     * last name and postcode but carries a different telephone. Determined once,
273	     * when the owner is created.
274	     */
275	    public Boolean getPossibleDuplicate() {
276	        return this.possibleDuplicate;
277	    }
278	
279	    public void setPossibleDuplicate(Boolean possibleDuplicate) {
280	        this.possibleDuplicate = possibleDuplicate;
281	    }
282	
283	    /**
284	     * The id of the existing owner this owner possibly duplicates, or {@code null}
285	     * when it has no such match.
286	     */
287	    public Integer getPossibleDuplicateOf() {
288	        return this.possibleDuplicateOf;
289	    }
290	
291	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
292	        this.possibleDuplicateOf = possibleDuplicateOf;
293	    }
294	
295	    protected Set<Pet> getPetsInternal() {
296	        if (this.pets == null) {
297	            this.pets = new HashSet<>();
298	        }
299	        return this.pets;
300	    }
301	
302	    protected void setPetsInternal(Set<Pet> pets) {
303	        this.pets = pets;
304	    }
305	
306	    public List<Pet> getPets() {
307	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
308	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
309	        return Collections.unmodifiableList(sortedPets);
310	    }
311	
312	    public void setPets(List<Pet> pets) {
313	        this.pets = new HashSet<>(pets);
314	    }
315	
316	    public void addPet(Pet pet) {
317	        getPetsInternal().add(pet);
318	        pet.setOwner(this);
319	    }
320	
321	    /**
322	     * Return the Pet with the given name, or null if none found for this Owner.
323	     *
324	     * @param name to test
325	     * @return true if pet name is already in use
326	     */
327	    public Pet getPet(String name) {
328	        return getPet(name, false);
329	    }
330	
331	    /**
332	     * Return the Pet with the given name, or null if none found for this Owner.
333	     *
334	     * @param name to test
335	     * @return true if pet name is already in use
336	     */
337	    public Pet getPet(String name, boolean ignoreNew) {
338	        name = name.toLowerCase();
339	        for (Pet pet : getPetsInternal()) {
340	            if (!ignoreNew || !pet.isNew()) {
341	                String compName = pet.getName();
342	                compName = compName.toLowerCase();
343	                if (compName.equals(name)) {
344	                    return pet;
345	                }
346	            }
347	        }
348	        return null;
349	    }
350	
351	    public Pet getPet(Integer petId) {
352	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
353	    }
354	
355	    @Override
356	    public String toString() {
357	        return new ToStringCreator(this)
358	
359	            .append("id", this.getId())
360	            .append("new", this.isNew())
361	            .append("lastName", this.getLastName())
362	            .append("firstName", this.getFirstName())
363	            .append("address", this.address)
364	            .append("city", this.city)
365	            .append("telephone", this.telephone)
366	            .append("email", this.email)
367	            .toString();
368	    }
369	}
