309	        String targetAddress = TextNormalizer.normalizeForComparison(address);
310	        return ownerRepository.findByLastNameIgnoreCase(lastName).stream()
311	            .filter(owner -> TextNormalizer.normalizeForComparison(owner.getLastName()).equals(targetLastName))
