319	        String householdId = HouseholdIdGenerator.generate(owner.getLastName(), owner.getAddress());
320	        owner.setHouseholdId(householdId);
321	        for (Owner member : existingMembers) {
322	            if (!householdId.equals(member.getHouseholdId())) {
323	                member.setHouseholdId(householdId);
324	                ownerRepository.save(member);
325	            }
326	        }
327	        return householdId;
328	    }
