65	@RestController
66	@CrossOrigin(exposedHeaders = "errors, content-type")
67	@RequestMapping("/api")
68	public class OwnerRestControllerV1 implements OwnersApi {
69	
70	    /**
71	     * Maximum number of owners a single city may hold. A create request whose city already contains
72	     * this many owners is rejected as a conflict.
73	     */
74	    static final int MAX_OWNERS_PER_CITY = 50;
75	
76	    /**
77	     * Maximum number of owners that may be registered on a single day. A create request whose
78	     * registration date already holds this many owners is rejected with 429 Too Many Requests.
79	     */
80	    static final int MAX_OWNERS_PER_DAY = 100;
81	
82	    /**
83	     * Number of owners that may be registered on the current business day before a create/read
84	     * response flags {@code bulkSignupWarning}. Once more than this many owners exist for the day,
85	     * the warning is raised.
86	     */
87	    static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
88	
89	    private final ClinicService clinicService;
90	
91	    private final OwnerMapper ownerMapper;
92	
93	    private final PetMapper petMapper;
94	
95	    private final VisitMapper visitMapper;
96	
97	    private final OwnerAuditor ownerAuditor;
98	
99	    public OwnerRestControllerV1(ClinicService clinicService,
100	                                 OwnerMapper ownerMapper,
101	                                 PetMapper petMapper,
102	                                 VisitMapper visitMapper,
103	                                 OwnerAuditor ownerAuditor) {
104	        this.clinicService = clinicService;
105	        this.ownerMapper = ownerMapper;
106	        this.petMapper = petMapper;
107	        this.visitMapper = visitMapper;
108	        this.ownerAuditor = ownerAuditor;
109	    }
110	
111	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
112	    @Override
113	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
114	        Collection<Owner> owners;
115	        if (lastName != null) {
116	            owners = this.clinicService.findOwnerByLastName(lastName);
117	        } else {
118	            owners = this.clinicService.findAllOwners();
119	        }
120	        if (owners.isEmpty()) {
121	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
122	        }
123	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
124	    }
125	
126	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
127	    @Override
128	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
129	        Owner owner = this.clinicService.findOwnerById(ownerId);
130	        if (owner == null) {
131	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
132	        }
133	        return new ResponseEntity<>(toOwnerDtoWithBulkSignupWarning(owner), HttpStatus.OK);
134	    }
135	
136	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
137	    @Override
138	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
139	        ownerFieldsDto.setAddress(AddressNormalizer.normalize(ownerFieldsDto.getAddress()));
140	        List<String> missingFields = OwnerFieldsValidator.findMissingFields(ownerFieldsDto);
141	        if (!missingFields.isEmpty()) {
142	            throw new MissingOwnerFieldsException(missingFields);
143	        }
144	        HttpHeaders headers = new HttpHeaders();
145	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
146	        if (!PostcodeValidator.isValidForCity(owner.getCity(), owner.getPostcode())) {
147	            throw new InvalidPostcodeException(owner.getPostcode(), owner.getCity());
148	        }
149	        if (this.clinicService.countOwnersByCity(owner.getCity()) >= MAX_OWNERS_PER_CITY) {
150	            throw new CityCapacityExceededException(owner.getCity());
151	        }
152	        if (RegistrationDatePolicy.isAfterServerDate(owner.getRegistrationDate())) {
153	            throw new FutureRegistrationDateException(owner.getRegistrationDate());
154	        }
155	        LocalDate registrationDate = RegistrationDatePolicy.effectiveDate(owner.getRegistrationDate());
156	        if (this.clinicService.countOwnersRegisteredOn(registrationDate) >= MAX_OWNERS_PER_DAY) {
157	            throw new DailyOwnerLimitExceededException(registrationDate);
158	        }
159	        owner.setTelephone(TelephoneNormalizer.normalize(owner.getTelephone()));
160	        owner.setEmail(EmailNormalizer.normalize(owner.getEmail()));
161	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
162	            Collection<Owner> household =
163	                this.clinicService.findOwnersInHousehold(owner.getLastName(), owner.getAddress());
164	            this.clinicService.joinHousehold(owner, household);
165	        }
166	        // A single identity key (telephone + email + household) drives duplicate detection: reject
167	        // only when the whole key already belongs to another owner.
168	        if (this.clinicService.isDuplicateIdentity(owner)) {
169	            throw new DuplicateIdentityException(owner.getIdentityKey());
170	        }
171	        this.clinicService.saveOwner(owner);
172	        this.ownerAuditor.ownerCreated(owner);
173	        OwnerDto ownerDto = toOwnerDtoWithBulkSignupWarning(owner);
174	        headers.setLocation(UriComponentsBuilder.newInstance()
175	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
176	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
177	    }
178	
179	    /**
180	     * Map an owner to its DTO and stamp {@code bulkSignupWarning}, which reflects whether more than
181	     * {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners have already been registered on the current
182	     * business day.
183	     */
184	    private OwnerDto toOwnerDtoWithBulkSignupWarning(Owner owner) {
185	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
186	        LocalDate today = RegistrationDatePolicy.effectiveDate(null);
187	        ownerDto.setBulkSignupWarning(
188	            this.clinicService.countOwnersRegisteredOn(today) > BULK_SIGNUP_WARNING_THRESHOLD);
189	        return ownerDto;
190	    }
