18	
19	import java.util.Locale;
20	import java.util.Map;
21	import java.util.regex.Pattern;
22	
23	/**
24	 * Normalizes an owner's postal address to its canonical stored form. Leading and trailing
25	 * whitespace is trimmed, every internal run of whitespace is collapsed to a single space, the
26	 * value is upper-cased, and common street-type abbreviations are expanded to their full words
27	 * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). The normalized address is
28	 * the value that is both persisted and used for every address comparison (household duplicate
29	 * detection and the shared household identifier), so those comparisons are insensitive to case,
30	 * spacing and abbreviation.
31	 */
32	public final class AddressNormalizer {
33	
34	    private static final Pattern WHITESPACE = Pattern.compile("\\s+");
35	
36	    /** Common street-type abbreviations expanded to their canonical full words. */
37	    private static final Map<String, String> ABBREVIATIONS = Map.of(
38	        "ST", "STREET",
39	        "RD", "ROAD",
40	        "AVE", "AVENUE");
41	
42	    private AddressNormalizer() {
43	    }
44	
45	    /**
46	     * Produces the canonical form of the supplied address.
47	     *
48	     * @param address the raw address as submitted, may be {@code null}
49	     * @return the normalized address, or an empty string when {@code address} is {@code null} or
50	     *     blank
51	     */
52	    public static String normalize(String address) {
53	        if (address == null) {
54	            return "";
55	        }
56	        String collapsed = WHITESPACE.matcher(address.trim()).replaceAll(" ").toUpperCase(Locale.ROOT);
57	        if (collapsed.isEmpty()) {
58	            return "";
59	        }
60	        String[] tokens = collapsed.split(" ");
61	        StringBuilder normalized = new StringBuilder(collapsed.length());
62	        for (int i = 0; i < tokens.length; i++) {
63	            if (i > 0) {
64	                normalized.append(' ');
65	            }
66	            normalized.append(ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
67	        }
68	        return normalized.toString();
69	    }
70	}
