36	
37	/**
38	 * Mostly used as a facade for all Petclinic controllers
39	 * Also a placeholder for @Transactional and @Cacheable annotations
40	 *
41	 * @author Michael Isvy
42	 * @author Vitaliy Fedoriv
43	 */
44	@Service
45	public class ClinicServiceImpl implements ClinicService {
46	
47	    private final PetRepository petRepository;
48	    private final VetRepository vetRepository;
49	    private final OwnerRepository ownerRepository;
50	    private final VisitRepository visitRepository;
51	    private final SpecialtyRepository specialtyRepository;
52	    private final PetTypeRepository petTypeRepository;
53	    private final CustomerCodeGenerator customerCodeGenerator;
54	    private final NamesakeCounter namesakeCounter;
55	    private final HouseholdMemberCounter householdMemberCounter;
56	    private final PossibleDuplicateDetector possibleDuplicateDetector;
57	
58	    public ClinicServiceImpl(
59	        PetRepository petRepository,
60	        VetRepository vetRepository,
61	        OwnerRepository ownerRepository,
62	        VisitRepository visitRepository,
63	        SpecialtyRepository specialtyRepository,
64	        PetTypeRepository petTypeRepository,
65	        CustomerCodeGenerator customerCodeGenerator,
66	        NamesakeCounter namesakeCounter,
67	        HouseholdMemberCounter householdMemberCounter,
68	        PossibleDuplicateDetector possibleDuplicateDetector) {
69	        this.petRepository = petRepository;
70	        this.vetRepository = vetRepository;
71	        this.ownerRepository = ownerRepository;
72	        this.visitRepository = visitRepository;
73	        this.specialtyRepository = specialtyRepository;
74	        this.petTypeRepository = petTypeRepository;
75	        this.customerCodeGenerator = customerCodeGenerator;
76	        this.namesakeCounter = namesakeCounter;
77	        this.householdMemberCounter = householdMemberCounter;
78	        this.possibleDuplicateDetector = possibleDuplicateDetector;
79	    }
80	
81	    @Override
82	    @Transactional(readOnly = true)
83	    public Collection<Pet> findAllPets() throws DataAccessException {
84	        return petRepository.findAll();
85	    }
86	
87	    @Override
88	    @Transactional(readOnly = true)
89	    public Page<Pet> findPets(Pageable pageable) throws DataAccessException {
90	        return petRepository.findAll(pageable);
91	    }
92	
93	    @Override
94	    @Transactional
95	    public void deletePet(Pet pet) throws DataAccessException {
96	        petRepository.delete(pet);
97	    }
98	
99	    @Override
100	    @Transactional(readOnly = true)
101	    public Visit findVisitById(int visitId) throws DataAccessException {
102	        return findEntityById(() -> visitRepository.findById(visitId));
103	    }
104	
105	    @Override
106	    @Transactional(readOnly = true)
107	    public Collection<Visit> findAllVisits() throws DataAccessException {
108	        return visitRepository.findAll();
109	    }
110	
111	    @Override
112	    @Transactional
113	    public void deleteVisit(Visit visit) throws DataAccessException {
114	        visitRepository.delete(visit);
115	    }
116	
117	    @Override
118	    @Transactional(readOnly = true)
119	    public Vet findVetById(int id) throws DataAccessException {
120	        return findEntityById(() -> vetRepository.findById(id));
121	    }
122	
123	    @Override
124	    @Transactional(readOnly = true)
125	    public Collection<Vet> findAllVets() throws DataAccessException {
126	        return vetRepository.findAll();
127	    }
128	
129	    @Override
130	    @Transactional
131	    public void saveVet(Vet vet) throws DataAccessException {
132	        vetRepository.save(vet);
133	    }
134	
135	    @Override
136	    @Transactional
137	    public void deleteVet(Vet vet) throws DataAccessException {
138	        vetRepository.delete(vet);
139	    }
140	
141	    @Override
142	    @Transactional(readOnly = true)
143	    public Collection<Owner> findAllOwners() throws DataAccessException {
144	        return ownerRepository.findAll();
145	    }
146	
147	    @Override
148	    @Transactional(readOnly = true)
149	    public Page<Owner> findOwners(String lastName, Pageable pageable) throws DataAccessException {
150	        if (lastName != null) {
151	            return ownerRepository.findByLastName(lastName, pageable);
152	        }
153	        return ownerRepository.findAll(pageable);
154	    }
155	
156	    @Override
157	    @Transactional
158	    public void deleteOwner(Owner owner) throws DataAccessException {
159	        ownerRepository.delete(owner);
160	    }
161	
162	    @Override
163	    @Transactional(readOnly = true)
164	    public PetType findPetTypeById(int petTypeId) {
165	        return findEntityById(() -> petTypeRepository.findById(petTypeId));
166	    }
167	
168	    @Override
169	    @Transactional(readOnly = true)
170	    public Collection<PetType> findAllPetTypes() throws DataAccessException {
171	        return petTypeRepository.findAll();
172	    }
173	
174	    @Override
175	    @Transactional
176	    public void savePetType(PetType petType) throws DataAccessException {
177	        petTypeRepository.save(petType);
178	    }
179	
180	    @Override
181	    @Transactional
182	    public void deletePetType(PetType petType) throws DataAccessException {
183	        petTypeRepository.delete(petType);
184	    }
185	
186	    @Override
187	    @Transactional(readOnly = true)
188	    public Specialty findSpecialtyById(int specialtyId) {
189	        return findEntityById(() -> specialtyRepository.findById(specialtyId));
190	    }
191	
192	    @Override
193	    @Transactional(readOnly = true)
194	    public Collection<Specialty> findAllSpecialties() throws DataAccessException {
195	        return specialtyRepository.findAll();
196	    }
197	
198	    @Override
199	    @Transactional
200	    public void saveSpecialty(Specialty specialty) throws DataAccessException {
201	        specialtyRepository.save(specialty);
202	    }
203	
204	    @Override
205	    @Transactional
206	    public void deleteSpecialty(Specialty specialty) throws DataAccessException {
207	        specialtyRepository.delete(specialty);
208	    }
209	
210	    @Override
211	    @Transactional(readOnly = true)
212	    public Collection<PetType> findPetTypes() throws DataAccessException {
213	        return petRepository.findPetTypes();
214	    }
215	
216	    @Override
217	    @Transactional(readOnly = true)
218	    public Owner findOwnerById(int id) throws DataAccessException {
219	        return findEntityById(() -> ownerRepository.findById(id));
220	    }
221	
222	    @Override
223	    @Transactional(readOnly = true)
224	    public Pet findPetById(int id) throws DataAccessException {
225	        return findEntityById(() -> petRepository.findById(id));
226	    }
227	
228	    @Override
229	    @Transactional
230	    public void savePet(Pet pet) throws DataAccessException {
231	        pet.setType(findPetTypeById(pet.getType().getId()));
232	        petRepository.save(pet);
233	    }
234	
235	    @Override
236	    @Transactional
237	    public void saveVisit(Visit visit) throws DataAccessException {
238	        visitRepository.save(visit);
239	
240	    }
241	
242	    @Override
243	    @Transactional(readOnly = true)
244	    public Collection<Vet> findVets() throws DataAccessException {
245	        return vetRepository.findAll();
246	    }
247	
248	    @Override
249	    @Transactional
250	    public void saveOwner(Owner owner) throws DataAccessException {
251	        if (owner.isNew()) {
252	            if (owner.getCustomerCode() == null) {
253	                owner.setCustomerCode(customerCodeGenerator.generate(owner));
254	            }
255	            owner.setNamesakeCount(namesakeCounter.count(owner));
256	            owner.setHouseholdSize(householdMemberCounter.count(owner));
257	            Owner possibleDuplicate = possibleDuplicateDetector.findPossibleDuplicate(owner);
258	            owner.setPossibleDuplicate(possibleDuplicate != null);
259	            owner.setPossibleDuplicateOf(possibleDuplicate == null ? null : possibleDuplicate.getId());
260	        }
261	        ownerRepository.save(owner);
262	
263	    }
264	
265	    @Override
266	    @Transactional(readOnly = true)
267	    public Collection<Owner> findOwnerByLastName(String lastName) throws DataAccessException {
268	        return ownerRepository.findByLastName(lastName);
269	    }
270	
271	    @Override
272	    @Transactional(readOnly = true)
273	    public Collection<Owner> findOwnerByTelephone(String telephone) throws DataAccessException {
274	        return ownerRepository.findByTelephone(telephone);
275	    }
276	
277	    @Override
278	    @Transactional(readOnly = true)
279	    public Collection<Owner> findOwnerByEmail(String email) throws DataAccessException {
280	        return ownerRepository.findByEmailIgnoreCase(email);
281	    }
282	
283	    @Override
284	    @Transactional(readOnly = true)
285	    public boolean isDuplicateIdentity(Owner owner) throws DataAccessException {
286	        String identityKey = owner.getIdentityKey();
287	        // The telephone is part of the identity key, so owners with a different telephone can never
288	        // share it: narrow by telephone, then confirm the whole key matches.
289	        return ownerRepository.findByTelephone(owner.getTelephone()).stream()
290	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
291	    }
292	
293	    @Override
294	    @Transactional(readOnly = true)
295	    public long countOwnersByCity(String city) throws DataAccessException {
296	        return ownerRepository.countByCity(city);
297	    }
298	
299	    @Override
300	    @Transactional(readOnly = true)
301	    public long countOwnersRegisteredOn(LocalDate registrationDate) throws DataAccessException {
302	        return ownerRepository.countByRegistrationDate(registrationDate);
303	    }
304	
305	    @Override
306	    @Transactional(readOnly = true)
307	    public Collection<Owner> findOwnersInHousehold(String lastName, String address) throws DataAccessException {
308	        String targetLastName = TextNormalizer.normalizeForComparison(lastName);
309	        String targetAddress = TextNormalizer.normalizeForComparison(address);
310	        return ownerRepository.findByLastNameIgnoreCase(lastName).stream()
311	            .filter(owner -> TextNormalizer.normalizeForComparison(owner.getLastName()).equals(targetLastName))
312	            .filter(owner -> TextNormalizer.normalizeForComparison(owner.getAddress()).equals(targetAddress))
313	            .collect(Collectors.toList());
314	    }
315	
316	    @Override
317	    @Transactional
318	    public String joinHousehold(Owner owner, Collection<Owner> existingMembers) throws DataAccessException {
319	        String householdId = HouseholdIdGenerator.generate(owner.getLastName(), owner.getAddress());
320	        owner.setHouseholdId(householdId);
321	        for (Owner member : existingMembers) {
322	            if (!householdId.equals(member.getHouseholdId())) {
323	                member.setHouseholdId(householdId);
324	                ownerRepository.save(member);
325	            }
326	        }
327	        return householdId;
328	    }
329	
330	    @Override
331	    @Transactional(readOnly = true)
332	    public Collection<Visit> findVisitsByPetId(int petId) {
333	        return visitRepository.findByPetId(petId);
334	    }
335	
336	    @Override
337	    @Transactional(readOnly = true)
338	    public List<Specialty> findSpecialtiesByNameIn(Set<String> names) {
339	        return findEntityById(() -> specialtyRepository.findSpecialtiesByNameIn(names));
340	    }
341	
342	    private <T> T findEntityById(Supplier<T> supplier) {
343	        try {
344	            return supplier.get();
345	        } catch (ObjectRetrievalFailureException | EmptyResultDataAccessException e) {
346	            // Just ignore not found exceptions for Jdbc/Jpa realization
347	            return null;
348	        }
349	    }
350	
351	}
